function dump(node, depth){
  const o = {id:node.id, name:node.name, type:node.type, x:node.x, y:node.y, w:node.width, h:node.height};
  if (node.type === 'COMPONENT' || node.type === 'COMPONENT_SET') o.key = node.key;
  if (node.fills && Array.isArray(node.fills)) o.fills = JSON.stringify(node.fills).slice(0,300);
  if (node.type === 'TEXT') { o.chars = node.characters; o.font = JSON.stringify(node.fontName); o.fs = node.fontSize; o.lh = JSON.stringify(node.lineHeight); o.ls = JSON.stringify(node.letterSpacing); }
  if (node.type === 'FRAME' && node.layoutMode !== 'NONE') o.auto = node.layoutMode;
  const kids = node.children ? node.children.map(c=>dump(c, depth+1)) : undefined;
  if (kids) o.children = kids;
  return o;
}
